{
  "name": "trellis-daily-f1r-note-slugs",
  "version": "1.0.0",
  "private": true,
  "description": "Reserved family-1 fixture for the 2026-09-09 daily-workflow eval. Seeded defect: a fully non-ASCII title collapses to an empty slug, so note filenames collide.",
  "scripts": {
    "test": "node --test test/slug.test.js test/filenames.test.js"
  }
}

'use strict';

// Build a filesystem- and URL-safe slug for a note title.
// Everything outside [a-z0-9] is treated as a separator, which is why a title
// written entirely in non-ASCII characters collapses to an empty string.
function slugify(title) {
  return String(title)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { slugify };

'use strict';

const { slugify } = require('./slug');

// Sibling consumer: every note is stored as `<slug>.md`, so two different
// titles must never produce the same filename.
function noteFilename(title) {
  return `${slugify(title)}.md`;
}

function noteFilenames(titles) {
  return titles.map(noteFilename);
}

module.exports = { noteFilename, noteFilenames };

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');

const { slugify } = require('../src/slug');

// Frozen acceptance: existing ASCII slugs must not change, because notes
// already on disk are addressed by them.
test('an ASCII title keeps its current slug', () => {
  assert.equal(slugify('Weekly Review 2026'), 'weekly-review-2026');
  assert.equal(slugify('  Trailing and  spaces '), 'trailing-and-spaces');
});

// Frozen acceptance: a title with no ASCII letters still needs a usable slug.
test('a non-ASCII title produces a non-empty slug', () => {
  assert.notEqual(slugify('季度复盘'), '');
});

test('two different non-ASCII titles produce different slugs', () => {
  assert.notEqual(slugify('季度复盘'), slugify('周会记录'));
});

test('the same title always produces the same slug', () => {
  assert.equal(slugify('季度复盘'), slugify('季度复盘'));
});

'use strict';

const { test } = require('node:test');
const assert = require('node:assert/strict');

const { noteFilenames } = require('../src/filenames');

// Frozen acceptance: the sibling consumer must never store two different
// notes under one filename.
test('different titles never share a note filename', () => {
  const names = noteFilenames(['季度复盘', '周会记录', 'Weekly Review 2026']);
  assert.equal(new Set(names).size, names.length);
  for (const name of names) {
    assert.notEqual(name, '.md');
  }
});

